        final Set<Entity> existing=Collections.newSetFromMap(new IdentityHashMap<>());final Set<Entity> mine=Collections.newSetFromMap(new IdentityHashMap<>());
        final Map<BlockPos,MapManager.BlockSnapshot> blocks=new LinkedHashMap<>();final int challenge,retainedHeaven,overheaven;final boolean offhand;
        Swap a,b;final Remote remote=new Remote();int phase,scenario,lastTick,working,sequence,paidShots,lastFrame=1;boolean animated;ItemStack gun;Vec3 origin;
        State(GameController game){this.game=game;level=game.maps().level();alpha=game.server().getPlayerList().getPlayer(GameChecks.offlineUuid("TestAlpha"));beta=game.server().getPlayerList().getPlayer(GameChecks.offlineUuid("TestBeta"));require(game.playing()&&alpha!=null&&beta!=null&&game.allowDamage(alpha)&&game.allowDamage(beta),"two actual participants");require(game.items().laserMinigun().spin(alpha)==0&&game.items().mobgun().cooldown(alpha)==0&&game.items().stand().cooldownTicks(alpha)==0&&game.items().stand().lightningCooldownTicks(alpha)==0&&game.items().timeStop().cooldownTicks(alpha)==0,"fixture starts with inactive owned counters");alphaState=new GameChecks.WandThirdPlayerState(alpha,game.items().mana());betaState=new GameChecks.WandThirdPlayerState(beta,game.items().mana());challenge=game.players().get(beta.getUUID()).lbcChallenge;retainedHeaven=game.players().get(alpha.getUUID()).standOverheavenMatches;overheaven=game.items().mana().hudValue(alpha,"overheaven");offhand=game.config().offhandWands;level.getAllEntities().forEach(existing::add);}
        void initialize(){a=new Swap(game,alpha);b=new Swap(game,beta);for(var p:List.of(alpha,beta)){p.closeContainer();p.stopUsingItem();p.getInventory().clearContent();p.inventoryMenu.setCarried(ItemStack.EMPTY);p.inventoryMenu.getCraftSlots().clearContent();p.setGameMode(GameType.SURVIVAL);p.setNoGravity(true);p.removeAllEffects();p.setDeltaMovement(Vec3.ZERO);}origin=new Vec3(alpha.getX(),Math.min(230,level.getMaxY()-20),alpha.getZ());alpha.teleportTo(level,origin.x,origin.y,origin.z,Set.of(),0,-90,true);beta.teleportTo(level,origin.x+20,origin.y,origin.z,Set.of(),0,0,true);ack(alpha,a.recorder);ack(beta,b.recorder);game.items().mana().set(alpha,100000);game.items().mana().maximum(alpha,100000);game.config().offhandWands=true;alpha.getInventory().setSelectedSlot(0);gun=new ItemStack(LbcLaserMinigun.ITEM);alpha.setItemInHand(InteractionHand.MAIN_HAND,gun);alpha.inventoryMenu.sendAllDataToRemote();remote.read(a.recorder);conserved("initial");lastTick=game.server().getTickCount();}
