        void click(int slot,int button,ContainerInput type,boolean stale){var menu=alpha.inventoryMenu;remote.read(a.recorder);/* This request declares EMPTY cursor prediction and no predicted slot mutations. Native corrections below must reconcile that exact client view. */remote.carried=ItemStack.EMPTY;alpha.connection.handleContainerClick(new ServerboundContainerClickPacket(menu.containerId,menu.getStateId()-(stale?1:0),(short)slot,(byte)button,type,new it.unimi.dsi.fastutil.ints.Int2ObjectOpenHashMap<>(),HashedStack.EMPTY));menu.broadcastChanges();remote.read(a.recorder);}
