        List<ItemEntity> dropped(){var out=new ArrayList<ItemEntity>();for(var e:level.getAllEntities())if(!existing.contains(e)&&e instanceof ItemEntity item&&!item.isRemoved()&&LbcLaserMinigun.isMinigun(item.getItem())){mine.add(item);out.add(item);}return out;}
        void conserved(String stage){int local=stored(),world=dropped().stream().mapToInt(e->e.getItem().getCount()).sum();require(local+world==1,"authoritative native minigun count conserved at "+stage+": menu="+local+" drops="+world);remote.read(a.recorder);require(remote.count()==local,"actual remote slot/cursor state matches server at "+stage+": client="+remote.count()+" server="+local);var out=net.minecraft.world.level.storage.TagValueOutput.createWithContext(net.minecraft.util.ProblemReporter.DISCARDING,level.registryAccess());net.fabricmc.fabric.api.networking.v1.context.PacketContext.supplyWithoutContext(()->{alpha.saveWithoutId(out);return null;});var data=out.buildResult();int savedInventory=0,savedEquipment=0;for(var raw:data.getListOrEmpty("Inventory"))if(raw instanceof CompoundTag row&&row.getStringOr("id","").equals("skywars2:laser_minigun"))savedInventory+=row.getIntOr("count",0);var equipment=data.getCompoundOrEmpty("equipment");for(var name:equipment.keySet()){var row=equipment.getCompoundOrEmpty(name);if(row.getStringOr("id","").equals("skywars2:laser_minigun"))savedEquipment+=row.getIntOr("count",0);}int saved=savedInventory+savedEquipment;int inventory=0;for(int i=0;i<alpha.getInventory().getContainerSize();i++){var s=alpha.getInventory().getItem(i);if(LbcLaserMinigun.isMinigun(s))inventory+=s.getCount();}require(saved==inventory,"native player serialization preserves exact physical gun count at "+stage+": savedInventory="+savedInventory+" savedEquipment="+savedEquipment+" physicalInventory="+inventory+" main="+alpha.getMainHandItem()+" offhand="+alpha.getOffhandItem()+" equipmentKeys="+equipment.keySet());}
        int slotWithGun(){for(int i=0;i<alpha.inventoryMenu.slots.size();i++)if(LbcLaserMinigun.isMinigun(alpha.inventoryMenu.slots.get(i).getItem()))return i;return -1;}
        void recover(){if(!alpha.inventoryMenu.getCarried().isEmpty())click(9,0,ContainerInput.PICKUP,false);for(var item:dropped()){item.setNoPickUpDelay();item.playerTouch(alpha);}int slot=slotWithGun();require(slot>=0,"native transfer/pickup recovers the sole physical gun");if(slot!=36)click(slot,0,ContainerInput.SWAP,false);alpha.inventoryMenu.broadcastChanges();remote.read(a.recorder);require(LbcLaserMinigun.isMinigun(alpha.getMainHandItem())&&alpha.getMainHandItem().getCount()==1,"native recovery returns one held copy");conserved("recovered scenario "+scenario);gun=alpha.getMainHandItem();}
        void transfer(){require(game.items().laserMinigun().spin(alpha)==30&&game.items().laserMinigun().shots(alpha)>paidShots,"actual sustained native input fired before transfer "+scenario);require(alpha.getMainHandItem()==gun&&LbcLaserMinigun.isMinigun(gun)&&animated,"actual animation mutates the held native stack in place");int full=remote.full;switch(scenario){case 0->click(36,0,ContainerInput.QUICK_MOVE,false);case 1->click(36,40,ContainerInput.SWAP,false);case 2->click(36,0,ContainerInput.THROW,false);case 3->click(36,0,ContainerInput.PICKUP,false);case 4->click(36,1,ContainerInput.SWAP,true);default->throw new IllegalStateException("Unknown menu scenario");}require(game.items().laserMinigun().spin(alpha)==0&&game.items().laserMinigun().inputGrace(alpha)==0,"actual native container click interrupts active motor/grace");require(remote.full>full,"actual interrupted native click sends canonical full slot/cursor snapshot");conserved("native click scenario "+scenario);recover();require(!alpha.getMainHandItem().getItem().use(level,alpha,InteractionHand.MAIN_HAND).consumesAction()&&game.items().laserMinigun().spin(alpha)==0,"same-tick queued native use cannot revive transaction-interrupted motor");scenario++;working=0;paidShots=game.items().laserMinigun().shots(alpha);animated=false;lastFrame=game.items().laserMinigun().frame(alpha,InteractionHand.MAIN_HAND);}
        Component latest(Recording r,int start){for(int i=r.packets.size()-1;i>=start;i--)if(r.packets.get(i) instanceof ClientboundSetActionBarTextPacket p)return p.text();throw new IllegalStateException("Expected actual actionbar packet, start="+start+" total="+r.packets.size());}
        Component pair(){int ai=a.recorder.packets.size(),bi=b.recorder.packets.size();game.items().refreshHud(alpha);game.items().refreshHud(beta);var source=latest(a.recorder,ai);var observer=latest(b.recorder,bi);require(source.equals(observer)&&alpha.getUUID().equals(game.items().hudSource(beta)),"actual observer camera packet equals source live HUD");return source;}
        void row(Component hud,String prefix,String value,int color){var list=hud.getSiblings();for(int i=0;i+1<list.size();i++)if(list.get(i).getString().equals(prefix)&&(value.equals("ready")?list.get(i+1).getContents() instanceof net.minecraft.network.chat.contents.TranslatableContents tr&&tr.getKey().equals("ready"):list.get(i+1).getString().equals(value))){var node=list.get(i+1);require(node.getStyle().getColor()!=null&&node.getStyle().getColor().getValue()==color,"source HUD numeric/ready color");return;}throw new IllegalStateException("Missing source HUD row "+prefix+value+" in "+hud.getString());}
        void timer(Item item,Runnable add,Runnable expire){alpha.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(item));alpha.setItemInHand(InteractionHand.OFF_HAND,ItemStack.EMPTY);game.items().invalidateHud(alpha);game.items().invalidateHud(beta);row(pair(),"    \uE104 ","ready",0x55ff55);add.run();row(pair(),"    \uE105 ","1",0xffffff);expire.run();row(pair(),"    \uE104 ","ready",0x55ff55);}
